<template>
  <div class="af-models" :class="{ 'af-models--nav-open': navOpen }">
    <div v-if="navOpen" class="af-sidebar-backdrop" @click="navOpen = false"></div>
    <AppSidebar />
    <main class="af-workspace">
      <header class="af-topbar">
        <div class="af-crumb"><el-button class="af-mobile-menu" type="text" icon="el-icon-s-fold" @click="navOpen = true" /><span>Agent组件</span><span class="af-crumb__sep">/</span><span class="af-crumb__current">{{ detail ? detail.name + ' · 工具列表' : 'HTTP 插件' }}</span></div>
        <div v-if="!detail" class="af-topbar__actions"><el-dropdown trigger="hover" @command="handleImportCommand"><el-button icon="el-icon-upload2">快捷导入 <i class="el-icon-arrow-down el-icon--right"></i></el-button><el-dropdown-menu slot="dropdown"><el-dropdown-item command="curl"><i class="el-icon-document"></i> 一键 CURL 导入</el-dropdown-item><el-dropdown-item command="json"><i class="el-icon-folder-opened"></i> 导入插件文件</el-dropdown-item></el-dropdown-menu></el-dropdown><el-button type="primary" icon="el-icon-plus" @click="openPlugin()">新建 HTTP 插件</el-button></div>
      </header>
      <section class="af-content"><div class="af-content__inner">
        <div v-if="detail" class="http-tools-page">
          <div class="http-detail__head"><div><el-button type="text" icon="el-icon-back" @click="backToPlugins">返回插件列表</el-button><h2>{{ detail.name }}</h2><p>{{ detail.baseUrl }} · {{ detail.alias }}__*</p></div><div><el-button icon="el-icon-upload2" @click="openToolImport">从 CURL 导入工具</el-button><el-button type="primary" icon="el-icon-plus" @click="openMethod()">新增接口工具</el-button></div></div>
          <div class="http-tools-card"><el-table :data="detail.methods || []" empty-text="暂无工具方法"><el-table-column label="工具"><template slot-scope="{row}"><b>{{ row.displayName || row.methodName }}</b><div class="http-tool-name">{{ row.toolName }}</div></template></el-table-column><el-table-column label="请求" width="280"><template slot-scope="{row}"><el-tag size="mini">{{ methodLabel(row.httpMethodType) }}</el-tag><code class="http-uri">{{ row.uri }}</code></template></el-table-column><el-table-column label="状态" width="110"><template slot-scope="{row}"><el-switch :value="row.status===1" @change="toggleMethod(row)"/></template></el-table-column><el-table-column label="操作" width="240"><template slot-scope="{row}"><el-button type="text" @click="openTest(row)">试运行</el-button><el-button type="text" @click="openMethod(row)">编辑</el-button><el-button type="text" class="af-text-danger" @click="removeMethod(row)">删除</el-button></template></el-table-column></el-table></div>
        </div>
        <template v-else>
        <div class="af-list-toolbar"><el-input v-model="keyword" class="af-list-toolbar__search" clearable prefix-icon="el-icon-search" placeholder="搜索插件名称或别名" @keyup.enter.native="load" /><el-select v-model="status" clearable placeholder="全部状态" @change="load"><el-option :value="1" label="已启用"/><el-option :value="0" label="已禁用"/></el-select><el-button icon="el-icon-refresh" :loading="loading" @click="load">刷新</el-button></div>
        <div v-if="loading" class="af-loading"><span class="af-spinner"></span>正在加载 HTTP 插件...</div>
        <div v-else-if="plugins.length" class="af-grid">
          <article v-for="plugin in plugins" :key="plugin.id" class="af-model-card http-card" @click="openDetail(plugin)">
            <div class="af-model-card__head"><span class="af-model-card__avatar http-plugin-avatar"><img v-if="plugin.icon" :src="plugin.icon" alt=""/><i v-else class="el-icon-link"></i></span><div class="af-model-card__heading"><div class="af-model-card__title"><span class="af-model-card__name">{{ plugin.name }}</span></div></div></div>
            <p class="af-model-card__desc">{{ plugin.description || '暂无描述' }}</p>
            <div class="http-base-url">{{ plugin.baseUrl }}</div>
            <div class="af-model-card__tags"><span class="af-tag" :class="plugin.status === 1 ? 'af-tag--brand' : ''">{{ plugin.status === 1 ? '已启用' : '已禁用' }}</span><span class="af-tag">{{ plugin.methodCount || 0 }} 个工具</span></div>
            <div class="af-model-card__footer"><div class="af-model-card__meta">{{ formatTime(plugin.modifyTime) }}</div><div class="af-model-card__ops"><button class="af-btn af-btn--ghost af-btn--sm" @click.stop="exportPlugin(plugin)">导出</button><button class="af-btn af-btn--ghost af-btn--sm" @click.stop="togglePlugin(plugin)">{{ plugin.status === 1 ? '禁用' : '启用' }}</button><button class="af-btn af-btn--ghost af-btn--sm" @click.stop="openPlugin(plugin)">编辑</button><button class="af-btn af-btn--ghost af-btn--sm af-btn--danger" @click.stop="removePlugin(plugin)">删除</button></div></div>
          </article>
        </div>
        <div v-else class="af-empty"><div class="af-empty__title">暂无 HTTP 插件</div><el-button type="primary" size="small" @click="openPlugin()">新建插件</el-button></div>
        <div v-if="total" class="af-pagination"><span class="af-pagination__summary">共 {{ total }} 个插件</span><el-pagination background layout="prev,pager,next,sizes" :total="total" :page-size="pageSize" :current-page="page" :page-sizes="[12,24,48]" @current-change="changePage" @size-change="changeSize" /></div>
        </template>
      </div></section>
    </main>

    <el-dialog :visible.sync="pluginDialog" :title="pluginForm.id ? '编辑 HTTP 插件' : '新建 HTTP 插件'" width="640px" :close-on-click-modal="false">
      <el-form label-width="104px"><el-form-item label="插件图标"><ImageUploadField v-model="pluginForm.icon"/></el-form-item><el-form-item label="插件名称" required><el-input v-model.trim="pluginForm.name" placeholder="例如：GitHub API"/></el-form-item><el-form-item label="插件别名" required><el-input v-model.trim="pluginForm.alias" :disabled="Boolean(pluginForm.id)" placeholder="例如：github"/><div class="af-form-tip">最终工具名为 alias__methodName，创建后建议不修改。</div></el-form-item><el-form-item label="Base URL" required><el-input v-model.trim="pluginForm.baseUrl" placeholder="https://api.example.com"/></el-form-item><el-form-item label="静态 Headers"><el-input v-model="headersJson" type="textarea" :rows="5" placeholder='{"Authorization":"Bearer xxx"}'/><div class="af-form-tip">敏感值保存后只显示 ******，原样提交表示保留。</div></el-form-item><el-form-item label="插件描述"><el-input v-model.trim="pluginForm.description" type="textarea" :rows="3"/></el-form-item></el-form>
      <span slot="footer"><el-button @click="pluginDialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="submitPlugin">保存</el-button></span>
    </el-dialog>

    <el-dialog :visible.sync="methodDialog" :title="methodForm.id ? '编辑 HTTP 工具' : '新建 HTTP 工具'" width="920px" top="5vh" :close-on-click-modal="false">
      <el-form label-width="104px" class="http-method-form"><div class="http-form-grid"><el-form-item label="工具名" required><el-input v-model.trim="methodForm.methodName" placeholder="get_user_repos"/></el-form-item><el-form-item label="展示名"><el-input v-model.trim="methodForm.displayName" placeholder="获取用户仓库"/></el-form-item><el-form-item label="HTTP Method" required><el-select v-model.number="methodForm.httpMethodType" style="width:100%"><el-option v-for="item in methods" :key="item.value" :label="item.label" :value="item.value"/></el-select></el-form-item><el-form-item label="URI" required><el-input v-model.trim="methodForm.uri" placeholder="/users/{username}/repos"/></el-form-item></div><el-form-item label="工具描述"><el-input v-model.trim="methodForm.methodDescription" type="textarea" :rows="2"/></el-form-item>
        <div class="http-param-head"><b>参数配置</b><el-button size="mini" icon="el-icon-plus" @click="addParam">添加参数</el-button></div>
        <el-table :data="methodForm.parameters" size="mini" border><el-table-column label="模型参数名" min-width="130"><template slot-scope="{row}"><el-input v-model.trim="row.methodParamName"/></template></el-table-column><el-table-column label="API 映射名" min-width="130"><template slot-scope="{row}"><el-input v-model.trim="row.mappedName"/></template></el-table-column><el-table-column label="位置" width="110"><template slot-scope="{row}"><el-select v-model.number="row.useTypeValue"><el-option v-for="item in uses" :key="item.value" :label="item.label" :value="item.value"/></el-select></template></el-table-column><el-table-column label="类型" width="110"><template slot-scope="{row}"><el-select v-model.number="row.dataTypeValue"><el-option v-for="item in types" :key="item.value" :label="item.label" :value="item.value"/></el-select></template></el-table-column><el-table-column label="描述" min-width="150"><template slot-scope="{row}"><el-input v-model="row.methodParamDescription"/></template></el-table-column><el-table-column label="默认值" min-width="130"><template slot-scope="{row}"><el-input v-model="row.defaultValue"/></template></el-table-column><el-table-column label="必填" width="65"><template slot-scope="{row}"><el-switch v-model="row.required" :active-value="1" :inactive-value="0"/></template></el-table-column><el-table-column width="56"><template slot-scope="{$index}"><el-button type="text" class="af-text-danger" icon="el-icon-delete" @click="methodForm.parameters.splice($index,1)"/></template></el-table-column></el-table>
      </el-form><span slot="footer"><el-button @click="methodDialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="submitMethod">保存工具</el-button></span>
    </el-dialog>

    <el-dialog :visible.sync="testDialog" :title="'测试运行 - '+(testMethod ? testMethod.methodName : '未知工具')" width="90%" top="5vh" :close-on-click-modal="false"><div v-if="testMethod" class="http-test-layout"><div class="http-test-panel"><div class="http-test-card"><h3>插件配置信息</h3><div class="http-test-info"><span><b>完整 URL：</b>{{ detail.baseUrl }}{{ testMethod.uri }}</span><span><b>HTTP 方法：</b><el-tag size="mini">{{ methodLabel(testMethod.httpMethodType) }}</el-tag></span></div></div><div class="http-test-card http-test-params"><h3>测试参数</h3><el-form label-width="130px"><el-form-item v-for="param in testMethod.parameters || []" :key="param.methodParamName" :label="param.methodParamName" :required="param.required===1"><el-input v-if="param.dataTypeValue!==5&&param.dataTypeValue!==6" v-model="testParams[param.methodParamName]" clearable :placeholder="param.defaultValue!=null?'默认值: '+param.defaultValue:'请输入'+param.methodParamName"><template slot="append"><span>{{ paramTypeLabel(param.dataTypeValue) }} · {{ param.required===1?'必填':'选填' }}</span></template></el-input><el-input v-else v-model="testParams[param.methodParamName]" type="textarea" :rows="4" :placeholder="param.dataTypeValue===5?'请输入 JSON 数组，例如：[1,2]':'请输入 JSON 对象，例如：{&quot;key&quot;:&quot;value&quot;}'"/><div v-if="param.methodParamDescription" class="af-form-tip">{{ param.methodParamDescription }}</div></el-form-item><div v-if="!(testMethod.parameters || []).length" class="http-test-empty">该工具无需输入参数</div></el-form></div><div class="http-test-actions"><el-button type="primary" icon="el-icon-video-play" :loading="testing" :disabled="!canRunTest()" @click="runTest">测试运行</el-button><el-button @click="resetTestParams">重置参数</el-button><el-button @click="testDialog=false">关闭</el-button></div></div><div class="http-test-panel"><div class="http-test-card http-test-result-card"><h3>运行结果</h3><div v-if="testing" class="http-test-state"><i class="el-icon-loading"></i><p>正在测试运行中...</p></div><div v-else-if="testResult" class="http-test-result-wrap"><el-alert v-if="!testResult.success" :title="testResult.error||'运行失败'" type="error" :closable="false"/><pre v-else class="http-test-result">{{ formatTestResult(testResult.result) }}</pre><div class="af-form-tip">耗时 {{ testResult.durationMs }} ms</div></div><div v-else class="http-test-state"><i class="el-icon-document"></i><p>运行结果将显示在这里</p></div></div></div></div></el-dialog>

    <el-dialog :visible.sync="pluginImportDialog" title="导入插件 - CURL命令" width="800px" top="5vh" :close-on-click-modal="false"><el-form label-width="100px"><el-form-item label="插件名称" required><el-input v-model.trim="pluginImportForm.pluginName" placeholder="请输入插件名称"/></el-form-item><el-form-item label="插件描述"><el-input v-model.trim="pluginImportForm.pluginDescription" type="textarea" :rows="3" maxlength="200" show-word-limit placeholder="请输入插件描述"/></el-form-item><el-form-item label="CURL命令" required><el-input v-model="pluginImportForm.curlCommand" type="textarea" :rows="8" resize="vertical" class="http-curl-input" placeholder="请输入CURL命令"/></el-form-item></el-form><span slot="footer"><el-button @click="pluginImportDialog=false">取 消</el-button><el-button type="primary" :loading="saving" @click="importPluginFromCurl">{{ saving ? '导入中...' : '确 定' }}</el-button></span></el-dialog>

    <el-dialog :visible.sync="jsonImportDialog" title="导入插件 - JSON文件" width="600px" top="5vh" :close-on-click-modal="false"><div class="http-sop-download"><div><b>如何快速制作插件文件？</b><p>下载 SOP，将同域名的一组接口快速转换为 AgentForge HTTP 插件文件。</p></div><el-button type="text" icon="el-icon-download" @click="downloadPluginFileSop">下载制作 SOP</el-button></div><el-form label-width="100px"><el-form-item label="JSON文件" required><el-upload class="http-json-upload" drag action="" :auto-upload="false" :limit="1" accept=".json,application/json" :file-list="jsonImportForm.fileList" :on-change="handleJsonFileChange" :on-remove="clearJsonImport"><i class="el-icon-upload"></i><div class="el-upload__text">将 JSON 插件文件拖到此处，或<em>点击选择文件</em></div><div slot="tip" class="el-upload__tip">支持拖拽或手动选择，每次只能导入 1 个 .json 文件</div></el-upload></el-form-item><el-form-item v-if="jsonImportForm.previewData" label="预览"><div class="http-json-preview"><p><b>插件名称：</b>{{ jsonImportForm.previewData.plugin.name || '—' }}</p><p><b>服务地址：</b>{{ jsonImportForm.previewData.plugin.baseUrl || '—' }}</p><p><b>描述：</b>{{ jsonImportForm.previewData.plugin.description || '—' }}</p><p><b>工具数量：</b>{{ (jsonImportForm.previewData.plugin.methods || []).length }} 个</p></div></el-form-item></el-form><span slot="footer"><el-button @click="jsonImportDialog=false">取 消</el-button><el-button type="primary" :disabled="!jsonImportForm.previewData" :loading="saving" @click="importFromJson">{{ saving ? '导入中...' : '确 定' }}</el-button></span></el-dialog>

    <el-dialog :visible.sync="toolImportDialog" title="导入工具 - CURL命令" width="800px" top="5vh" :close-on-click-modal="false"><el-alert class="http-import-tip" title="CURL 请求地址需与当前插件的 Base URL 保持相同前缀" type="info" :closable="false" show-icon><div slot="description">当前 Base URL：<code>{{ detail ? detail.baseUrl : '—' }}</code>，导入后仅保留后续路径作为接口 URI。</div></el-alert><el-form label-width="100px"><el-form-item label="CURL命令" required><el-input v-model="toolImportForm.curlCommand" type="textarea" :rows="8" resize="vertical" class="http-curl-input" placeholder="请输入CURL命令"/></el-form-item></el-form><span slot="footer"><el-button @click="toolImportDialog=false">取 消</el-button><el-button type="primary" :loading="saving" @click="importToolFromCurl">{{ saving ? '导入中...' : '确 定' }}</el-button></span></el-dialog>
  </div>
</template>

<script>
import AppSidebar from '../../components/AppSidebar.vue'
import ImageUploadField from '../../components/ImageUploadField.vue'
import { pageHttpPlugins, getHttpPlugin, saveHttpPlugin, setHttpPluginStatus, deleteHttpPlugin, getHttpMethod, saveHttpMethod, setHttpMethodStatus, deleteHttpMethod, testHttpMethod, importCurl, importPluginJson, exportPluginJson } from '../../api/httpPlugin'
const emptyPlugin = () => ({ id: null, name: '', alias: '', baseUrl: '', description: '', icon: '', status: 1 })
const emptyMethod = (pluginId) => ({ id: null, pluginId, methodName: '', displayName: '', methodDescription: '', httpMethodType: 1, uri: '/', status: 1, sortOrder: 0, parameters: [] })
export default {
  name: 'HttpPluginPage', components: { AppSidebar, ImageUploadField },
  data() { return { navOpen:false,loading:false,saving:false,testing:false,keyword:'',status:null,page:1,pageSize:12,total:0,plugins:[],pluginDialog:false,pluginForm:emptyPlugin(),headersJson:'{}',detail:null,methodDialog:false,methodForm:emptyMethod(null),testDialog:false,testMethod:null,testParams:{},testResult:null,pluginImportDialog:false,pluginImportForm:{pluginName:'',pluginDescription:'',curlCommand:''},jsonImportDialog:false,jsonImportForm:{fileList:[],jsonData:null,previewData:null},toolImportDialog:false,toolImportForm:{pluginId:null,curlCommand:''},methods:[{value:1,label:'GET'},{value:2,label:'POST'},{value:3,label:'PUT'},{value:4,label:'DELETE'},{value:5,label:'PATCH'}],uses:[{value:1,label:'Query'},{value:2,label:'Body'},{value:3,label:'Path'},{value:4,label:'Header'}],types:[{value:1,label:'String'},{value:2,label:'Integer'},{value:3,label:'Number'},{value:4,label:'Boolean'},{value:5,label:'Array'},{value:6,label:'Object'}] } },
  created(){this.load();this.loadDetailFromRoute()},
  beforeRouteUpdate(to,from,next){this.loadDetailFromRoute(to);next()},
  methods:{
    async loadDetailFromRoute(route=this.$route){const raw=route.query.pluginId;const id=Array.isArray(raw)?raw[0]:raw;if(!id){this.detail=null;return}try{this.detail=await getHttpPlugin(id)}catch(e){this.detail=null;this.toast(e.message,true)}},
    async load(){this.loading=true;try{const r=await pageHttpPlugins({keyword:this.keyword,status:this.status,page:this.page,pageSize:this.pageSize});this.plugins=r.data||[];this.total=r.totalCount||0}catch(e){this.toast(e.message,true)}finally{this.loading=false}},
    changePage(v){this.page=v;this.load()},changeSize(v){this.pageSize=v;this.page=1;this.load()},formatTime(v){return v?new Date(v).toLocaleString('zh-CN',{hour12:false}):'—'},methodLabel(v){return (this.methods.find(x=>x.value===v)||{}).label||v},
    async openPlugin(item){this.pluginForm=item?{...(await getHttpPlugin(item.id))}:emptyPlugin();this.headersJson=JSON.stringify(this.pluginForm.staticHeaders||{},null,2);this.pluginDialog=true},
    async submitPlugin(){let headers;try{headers=JSON.parse(this.headersJson||'{}')}catch(_e){return this.toast('Headers 必须是合法 JSON 对象',true)}this.saving=true;try{await saveHttpPlugin({...this.pluginForm,staticHeaders:headers});this.pluginDialog=false;await this.load();this.toast('插件已保存')}catch(e){this.toast(e.message,true)}finally{this.saving=false}},
    async togglePlugin(item){try{await setHttpPluginStatus(item.id,item.status===1?0:1);await this.load()}catch(e){this.toast(e.message,true)}},
    async removePlugin(item){try{await this.$confirm('删除后关联 Agent 将跳过该插件，是否继续？','删除 HTTP 插件',{type:'warning'});await deleteHttpPlugin(item.id);await this.load();this.toast('插件已删除')}catch(e){if(e!=='cancel'&&e!=='close')this.toast(e.message||String(e),true)}},
    async exportPlugin(item){try{const data=await exportPluginJson(item.id);const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json;charset=utf-8'});const link=document.createElement('a');const url=URL.createObjectURL(blob);link.href=url;link.download=(item.name||'http-plugin').replace(/[\\/:*?"<>|]/g,'_')+'.json';document.body.appendChild(link);link.click();document.body.removeChild(link);URL.revokeObjectURL(url);this.toast('插件配置已导出')}catch(e){this.toast('导出失败：'+e.message,true)}},
    openDetail(item){this.$router.push({path:'/http-plugins',query:{pluginId:item.id}})},backToPlugins(){this.$router.push('/http-plugins')},async refreshDetail(){if(this.detail)this.detail=await getHttpPlugin(this.detail.id)},
    async openMethod(item){this.methodForm=item?await getHttpMethod(item.id):emptyMethod(this.detail.id);this.methodForm.parameters=this.methodForm.parameters||[];this.methodDialog=true},addParam(){this.methodForm.parameters.push({methodParamName:'',mappedName:'',methodParamDescription:'',useTypeValue:1,dataTypeValue:1,defaultValue:null,required:0,sortOrder:this.methodForm.parameters.length})},
    async submitMethod(){this.saving=true;try{await saveHttpMethod(this.methodForm);this.methodDialog=false;await this.refreshDetail();await this.load();this.toast('工具已保存')}catch(e){this.toast(e.message,true)}finally{this.saving=false}},async toggleMethod(row){try{await setHttpMethodStatus(row.id,row.status===1?0:1);await this.refreshDetail()}catch(e){this.toast(e.message,true)}},async removeMethod(row){try{await this.$confirm('确认删除该 HTTP 工具？','提示',{type:'warning'});await deleteHttpMethod(row.id);await this.refreshDetail();await this.load()}catch(e){if(e!=='cancel'&&e!=='close')this.toast(e.message||String(e),true)}},
    async openTest(row){try{this.testMethod=await getHttpMethod(row.id);this.resetTestParams();this.testResult=null;this.testDialog=true}catch(e){this.toast(e.message,true)}},resetTestParams(){const values={};for(const param of (this.testMethod&&this.testMethod.parameters)||[])values[param.methodParamName]=param.defaultValue==null?'':String(param.defaultValue);this.testParams=values;this.testResult=null},paramTypeLabel(v){return (this.types.find(x=>x.value===v)||{}).label||v},canRunTest(){return ((this.testMethod&&this.testMethod.parameters)||[]).every(param=>param.required!==1||(this.testParams[param.methodParamName]!==undefined&&this.testParams[param.methodParamName]!==''))},convertTestParam(value,type){if(value===''||value===undefined)return undefined;if(type===2||type===3){const n=Number(value);if(Number.isNaN(n))throw new Error('数值参数格式不正确');return n}if(type===4){if(value===true||value==='true'||value==='1')return true;if(value===false||value==='false'||value==='0')return false;throw new Error('布尔参数请输入 true 或 false')}if(type===5||type===6){try{const parsed=JSON.parse(value);if(type===5&&!Array.isArray(parsed))throw new Error();if(type===6&&(parsed===null||Array.isArray(parsed)||typeof parsed!=='object'))throw new Error();return parsed}catch(_e){throw new Error(type===5?'请输入合法的 JSON 数组':'请输入合法的 JSON 对象')}}return value},async runTest(){if(!this.canRunTest())return this.toast('请填写所有必填参数',true);let args={};try{for(const param of this.testMethod.parameters||[]){const value=this.convertTestParam(this.testParams[param.methodParamName],param.dataTypeValue);if(value!==undefined)args[param.methodParamName]=value}}catch(e){return this.toast(e.message,true)}this.testing=true;this.testResult=null;try{this.testResult=await testHttpMethod(this.testMethod.id,args)}catch(e){this.testResult={success:false,error:e.message,durationMs:0}}finally{this.testing=false}},formatTestResult(value){if(typeof value!=='string')return JSON.stringify(value,null,2);try{return JSON.stringify(JSON.parse(value),null,2)}catch(_e){return value}},
