trim())return this.toast('请输入CURL命令',true);this.saving=true;try{await importCurl(this.toolImportForm);this.toolImportDialog=false;await this.refreshDetail();await this.load();this.toast('工具导入成功')}catch(e){this.toast(e.message,true)}finally{this.saving=false}},toast(message,error=false){this.$message({message,type:error?'error':'success'})}
